/// The hasher the style engine's maps use, re-exported so korvus-page takes it from here: a new
/// dependency edge moves every downstream crate's metadata hash, so their `TypeId`s and so the order of
/// deno_core's per-type `OpState` map, which per-call lookups pay for by position (appendChild +11 %).
pub use rustc_hash::{FxHashMap, FxHashSet};
// `ShadowInfo` is NOT re-exported (W9.10). It is the crate's own record of a host<->root edge, kept
// in the `pub(crate)` `shadow_roots` map; no crate outside this one has ever named it, and no public
// signature takes or returns one. Re-exporting it published an internal shape as API, which is how a
// field becomes impossible to change later for a reason nobody wrote down.
pub use atom::Atom;
pub use tree::{
    AttachShadowError, DoctypeData, DocumentMode, Dom, ElementNs, Node, NodeId, NodeKind, PiData, ShadowRootMode, ShadowSlotAssignment,
    NS_HTML, NS_MATHML, NS_SVG, NS_XML,
};
